"    let subtotal, discountAmt, cgst, sgst, serviceCharge, extraFixed, total, couponDiscountAmt, pointsDiscountAmt;
    if (isFreeCheckout) {
      // Free mode: all items are complementary, all financials are zero
      subtotal = 0; discountAmt = 0; cgst = 0; sgst = 0; serviceCharge = 0; extraFixed = 0; total = 0;
      couponDiscountAmt = 0; pointsDiscountAmt = 0;
    } else {
      ({ subtotal, discountAmt, cgst, sgst, serviceCharge, extraFixed, total, couponDiscountAmt, pointsDiscountAmt } = calculateTotals(activeCart));
    }
    const grandTotal = isFreeCheckout ? 0 : total + (parseFloat(tip) || 0);"

